import requests

def solve(inputs):
    """
    Updates the authenticated user's name via GitHub REST API version 2026-03-10.

    Args:
        inputs (dict): A dictionary containing:
            - 'new_name': The new name for the authenticated user.
            - 'credential': The authentication credential (e.g., token or username/password).

    Returns:
        None if the response is empty (success), otherwise returns the decoded JSON response.

    Raises:
        Exception: If the HTTP response indicates an error (non-2xx status code).
    """
    new_name = inputs['new_name']
    credential = inputs['credential']

    # GitHub API endpoint for updating user information
    url = "https://api.github.com/user"

    headers = {
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2026-03-10'
    }

    # Prepare authentication based on credential type (assuming token for simplicity)
    if isinstance(credential, str) and credential.startswith('ghp_'):
        auth = {'token': credential}
    elif isinstance(credential, dict):
        # If credential is a dict, assume it contains 'username' and 'password' or 'token'
        if 'token' in credential:
            auth = {'token': credential['token']}
        else:
            auth = {'username': credential.get('username'), 'password': credential.get('password')}
    else:
        raise ValueError("Unsupported credential format. Expected a token string or dict with 'token'.")

    params = {'name': new_name}

    response = requests.put(url, headers=headers, auth=auth, json=params)

    if response.status_code == 204:
        return None
    elif response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Failed to update user name. Status code: {response.status_code}, Response: {response.text}")

import requests
from requests.exceptions import HTTPError, RequestException

def solve(inputs):
    """
    Creates a milestone in a GitHub repository using the REST API.

    Args:
        inputs (dict): A dictionary containing:
            - repository_owner (str): The account owner of the repository.
            - repository_name (str): The name of the repository without the .git extension.
            - new_state (str): Value for the state attribute ('open' or 'closed').
            - new_title (str): Value for the title attribute.
            - credential (dict): Caller-supplied credential with necessary permissions.

    Returns:
        dict or None: The decoded JSON response if successful, None for an empty response.

    Raises:
        Exception: For unsuccessful HTTP responses.
    """
    try:
        url = f"https://api.github.com/repos/{inputs['repository_owner']}/{inputs['repository_name']}/milestones"

        headers = {
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2026-03-10"
        }

        payload = {
            "title": inputs["new_title"],
            "state": inputs["new_state"]
        }

        response = requests.post(url, json=payload, headers=headers, auth=inputs["credential"])

        if response.status_code == 201:
            return None
        elif response.status_code == 200:
            return response.json()
        else:
            response.raise_for_status()
    except HTTPError as http_err:
        raise Exception(f"HTTP error occurred: {http_err}")
    except RequestException as req_err:
        raise Exception(f"Request error occurred: {req_err}")

