    Args:
        inputs (dict): A dictionary containing:
            - 'new_name': str, value for the name attribute of the new pet.
            - 'new_photo_links': list[str] or str, value for the photoUrls attribute.
            - 'new_status': str, value for the status attribute of the new pet.
            - 'credential': dict, caller-supplied credential (e.g., {'username': ..., 'password': ...}).

    Returns:
        str or None: The response's 'name' value if present, otherwise None for a successful empty response.

    Raises:
        Exception: If the HTTP response indicates an unsuccessful status code.
    """
    base_url = "https://petstore.swagger.io/v2"
    url = f"{base_url}/pet"

    # Prepare the payload according to OpenAPI 3 Petstore schema for POST /pet
    payload = {
        "name": inputs["new_name"],
        "photoUrls": inputs["new_photo_links"] if isinstance(inputs["new_photo_links"], list) else [inputs["new_photo_links"]],
        "status": inputs["new_status"]
    }

    # Prepare headers with Bearer token or Basic Auth depending on credential structure.
    # Assuming 'credential' is a dict like {'username': ..., 'password': ...} for Basic Auth.
    if isinstance(inputs["credential"], dict) and "username" in inputs["credential"] and "password" in inputs["credential"]:
        auth = requests.auth.HTTPBasicAuth(
            inputs["credential"]["username"],
            inputs["credential"]["password"]
        )
        headers = {}  # No special headers needed beyond auth
    elif isinstance(inputs["credential"], str):
        # Assume it's a Bearer token string
        headers = {"Authorization": f"Bearer {inputs['credential']}"}
        auth = None
    else:
        raise ValueError("Unsupported credential format. Expected dict with 'username'/'password' or a Bearer token string.")

    response = requests.post(url, json=payload, auth=auth, headers=headers)

    if response.status_code == 201:
        # Successful creation; check for 'name' in response JSON
